genesis_configure_proxy() { if [ -z "${HTTPS_PROXY:-${https_proxy:-}}" ] && [ -z "${ALL_PROXY:-${all_proxy:-}}" ] && command -v scutil >/dev/null 2>&1; then local genesis_proxy; genesis_proxy="$(scutil --proxy 2>/dev/null | /usr/bin/awk '/HTTPSEnable :/ {e=$3} /HTTPSProxy :/ {h=$3} /HTTPSPort :/ {p=$3} END {if(e==1 && h!="" && p!="") printf "http://%s:%s",h,p}')"; if [ -n "$genesis_proxy" ]; then export HTTPS_PROXY="$genesis_proxy"; fi; fi; }; genesis_configure_proxy
